import time

from fractions import Fraction


class TokenBucket:
    """A token bucket rate limiter. See TASK.md."""

    def __init__(self, rate, capacity, clock=time.monotonic):
        if not self._positive(rate) or not self._positive(capacity):
            raise ValueError("rate and capacity must be greater than 0")
        self._rate = rate
        self._capacity = capacity
        self._clock = clock
        self._tokens = capacity
        self._last = clock()

    @staticmethod
    def _positive(x):
        try:
            return x > 0
        except TypeError:
            return False

    def _sync(self):
        now = self._clock()
        last = self._last
        if now < last:
            # Clock moved backward: this step adds and removes nothing.
            return
        dt = now - last
        self._last = now
        gain = self._rate * dt
        self._tokens = self._tokens + gain
        if self._tokens > self._capacity:
            self._tokens = self._capacity

    def available(self):
        self._sync()
        return self._tokens

    def take(self, cost=1):
        if not self._positive(cost) or cost > self._capacity:
            raise ValueError("cost must be greater than 0 and at most capacity")
        self._sync()
        if self._tokens >= cost:
            self._tokens = self._tokens - cost
            return True
        return False

    def wait_time(self, cost=1):
        if not self._positive(cost) or cost > self._capacity:
            raise ValueError("cost must be greater than 0 and at most capacity")
        self._sync()
        if self._tokens >= cost:
            return 0
        deficit = cost - self._tokens
        if isinstance(deficit, float) or isinstance(self._rate, float):
            return deficit / self._rate
        return Fraction(deficit) / self._rate
